#!/usr/bin/env bash
set -euo pipefail
[[ $# -eq 7 ]] || { echo "usage: $0 GPU control|dual LABEL OUTPUT_ROOT SEED left|right pilot|natural" >&2; exit 2; }
repo=/home/baoquanc/workspace/DoorDog-A2_Piper;py=/home/baoquanc/anaconda3/envs/isaaclab/bin/python;gpu=$1;view=$2;label=$3;root=$4;seed=$5;side=$6;mode=$7;source="$repo/logs_rl/by_batch/base_v26_acquisition_supplement_20260823/continuation/V26A_LR_S1_POLICY800/model_step_002000.pt"
[[ "$gpu" =~ ^[45]$ && "$view" =~ ^(control|dual)$ && "$seed" =~ ^[01]$ && "$side" =~ ^(left|right)$ && "$mode" =~ ^(pilot|natural)$ && -f "$source" ]] || exit 2
case "$view" in control) selector=wbmanip/base_v26_5_eval_O0A0;identity=true;residual=false;shared=false;;dual) selector=wbmanip/base_v26_5_wave2_R15_eval_policy_residual;identity=false;residual=true;shared=true;;esac
output="$root/$view/$label/$side";[[ ! -e "$output" ]] || { echo "R15 output exists: $output" >&2;exit 1; }
extra=(++algo.config.eval.a2_v26_5_post_construction_reseed_pilot_trace=false);[[ "$mode" == pilot ]] && extra=(++algo.config.eval.a2_v26_5_post_construction_reseed_pilot_trace=true ++env.config.max_episode_length_s=.98)
env CUDA_VISIBLE_DEVICES="$gpu" CUDA_DEVICE_ORDER=PCI_BUS_ID ACCELERATE_TORCH_DEVICE=cuda:0 WANDB_MODE=disabled HYDRA_FULL_ERROR=1 PYTHONUNBUFFERED=1 PYTHONPATH="$repo" "$py" -B -m gr00t.rl.eval_agent_trl +ablation="$selector" ++checkpoint="$source" ++checkpoint_load_mode=policy_only ++policy_only_load_actor_rms=true ++auto_load_latest=false ++seed="$seed" ++num_envs=64 ++algo.config.eval.a2_v23_p06_policy_only=false ++algo.config.eval.a2_v26_5_policy_only_identity_control="$identity" ++algo.config.eval.a2_v26_5_policy_only_residual="$residual" ++algo.config.eval.a2_v26_5_runtime_load_receipt=true ++algo.config.eval.a2_v26_5_post_construction_reseed=true "${extra[@]}" ++algo.config.eval.num_eval_episodes=64 ++algo.config.eval.eval_num_envs_episodes=true ++algo.config.eval.dump_to_log_metrics=true ++algo.config.eval.a2_diagnostic_trace_enabled=true ++algo.config.eval.a2_diagnostic_reward_terms='[push_door_handle,a2_stage3_unlatch_hold,push_door_hinge,a2_stage3_stage4_hold_and_drive]' ++algo.config.eval.a2_forced_gripper_close_enabled=false ++algo.config.eval.a2_stage2_close_gate_forced_gripper_close_enabled=false ++env.config.a2_v26_5_shared_residual_observation_enabled="$shared" ++env.config.a2_v26_2_telemetry_enabled=true ++env.config.a2_v26_3_telemetry_enabled=true ++env.config.a2_v26_2_handle_depression_scale=0.0 ++env.config.a2_v26_3_handle_creation_scale=0.0 ++env.config.a2_v26_door_open_lr="$side" ++env.config.a2_v26_side_permutation_seed="$seed" ++env.config.enable_staged_reset=false ++eval_output_dir="$output"
for x in a2_v26_5_runtime_load_receipt.json a2_v26_5_post_construction_reseed_receipt.json metrics_eval.json a2_v14_per_env_records.json stage2_5_step_trace.json a2_eval_diagnostic_metadata.json;do [[ -f "$output/$x" ]] || { echo "missing R15 artifact: $output/$x" >&2;exit 1;};done
[[ "$mode" == natural ]] || [[ -f "$output/a2_v26_5_post_construction_reseed_trace.json" ]] || exit 1
